import heroesData from "../data/UI/heroes.json";
import HeroCard from "../components/UI/HeroCard";
import HeroModal from "../components/UI/HeroModal";
import FilterBar from "../components/UI/FilterBar";
import { useState } from "react";

const Home = () => {
  const [heroes] = useState(heroesData);
  const [selectedHero, setSelectedHero] = useState(null);
  const [search, setSearch] = useState("");
  const [selectedRole, setSelectedRole] = useState("All");

  const filteredHeroes = heroes.filter((h) => {
    const matchesSearch = h.name.toLowerCase().includes(search.toLowerCase());
    const matchesRole = selectedRole === "All" || h.role === selectedRole;
    return matchesSearch && matchesRole;
  });

  return (
    <div className="min-h-screen bg-gradient-to-b from-black via-slate-900 to-slate-800 text-white p-6">
      <h1 className="text-4xl font-extrabold text-center mb-8">
        Marvel Rivals Hero Showcase
      </h1>
      <FilterBar {...{ search, setSearch, selectedRole, setSelectedRole }} />
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {filteredHeroes.map((hero) => (
          <HeroCard key={hero.id} hero={hero} onSelect={setSelectedHero} />
        ))}
      </div>
      {selectedHero && (
        <HeroModal hero={selectedHero} onClose={() => setSelectedHero(null)} />
      )}
    </div>
  );
};

export default Home;
